package com.labex.labexagent.run;
import com.labex.entity.AgentModelConfig;import com.labex.entity.AgentSubagent;import com.labex.labexagent.llm.LlmProvider;import com.labex.labexagent.llm.LlmProviderFactory;import com.labex.labexagent.runtime.AgentContext;import com.labex.service.AgentModelConfigService;import java.util.List;import java.util.Map;import org.springframework.stereotype.Component;
@Component public class LlmSubagentExecutor implements SubagentExecutor {
 private final LlmProviderFactory providers;private final AgentModelConfigService configs;private final AgentSubagentEventService events;
 public LlmSubagentExecutor(LlmProviderFactory providers,AgentModelConfigService configs,AgentSubagentEventService events){this.providers=providers;this.configs=configs;this.events=events;}
 public String execute(AgentContext context,AgentSubagent subagent){if(subagent.getInstructions()==null||subagent.getInstructions().isBlank())throw new IllegalArgumentException("subagent instructions are required");AgentModelConfig config=configs.resolveForStudent(context.getStudentId(),subagent.getModelConfigId());LlmProvider provider=providers.resolveProvider(config);StringBuilder output=new StringBuilder();provider.chatStream("You are a focused subagent. Return a concise evidence-based result.",List.of(Map.of("role","user","content",subagent.getInstructions())),List.of(),providers.buildConfig(config),context.getCancellationToken(),chunk->{if(chunk.content()!=null&&!chunk.content().isBlank()){output.append(chunk.content());events.append(subagent.getSubagentId(),"DELTA",chunk.content());}});return output.toString();}
}
